package co.fallsoft.pocket
import org.junit.Assert.*
import org.junit.Test
class DisplayedSpeechSessionTest {
 @Test fun restoresCursorAndNotificationsArrivingDuringManualReading(){val auto=SpeechQueue(mutableListOf(SpokenMessage(1,"a","complete","first")),3,740);val session=DisplayedSpeechSession();val manual=session.start("chat",auto,SpokenMessage(-1,"chat","displayed","manual"));session.parked!!.enqueue(SpokenMessage(2,"b","complete","arrived"));manual.pause(100,"pause");assertNull(session.stop("other"));val restored=session.stop("chat")!!;assertSame(auto,restored);assertEquals(listOf(1L,2L),restored.messages.map{it.id});assertEquals(3,restored.chunkIndex);assertEquals(740,restored.positionMs);assertTrue(restored.paused);assertFalse(restored.completed(-1,0))}
 @Test fun replacingOwnerNeverParksOrRestoresTheTemporaryManualQueue(){val auto=SpeechQueue(mutableListOf(SpokenMessage(5,"a","complete","auto")),2,900);val session=DisplayedSpeechSession();val first=session.start("a",auto,SpokenMessage(-1,"a","displayed","first"));session.start("b",first,SpokenMessage(-2,"b","displayed","second"));assertNull(session.stop("a"));assertSame(auto,session.stop("b"));assertEquals(900,auto.positionMs);assertTrue(auto.paused)}
 @Test fun completionAndLateOldCallbacksCannotAdvanceRestoredNotification(){val auto=SpeechQueue(mutableListOf(SpokenMessage(8,"a","complete","saved notification")),0,321);val session=DisplayedSpeechSession();val manual=session.start("owner",auto,SpokenMessage(-1,"manual","displayed","one sentence"));assertTrue(manual.completed(-1,0));assertNull(manual.current);val restored=session.stop("owner")!!;assertEquals(321,restored.positionMs);assertFalse(restored.completed(-1,0));assertEquals(8L,restored.current!!.id);assertEquals(0,restored.chunkIndex);assertTrue(restored.paused)}
}
